param($Request,$TriggerMetadata)
. "$PSScriptRoot\..\shared\Storage.ps1"
try{$table=Get-TableHandle $env:CERTAMENT_LATEST_TABLE;$rows=@(Get-AzTableRow -table $table);Push-OutputBinding -Name Response -Value (New-MonitoringResponse 200 @($rows|ForEach-Object{[pscustomobject]@{installationId=$_.InstallationId;server=$_.Server;customer=$_.Customer;version=$_.Version;status=$_.Status;timestampUtc=$_.TimestampUtc;certificateDaysRemaining=$_.CertificateDaysRemaining;stage=$_.Stage;detail=$_.Detail;notificationStatus=$_.NotificationStatus}}))}catch{Write-Error $_;Push-OutputBinding -Name Response -Value (New-MonitoringResponse 500 @{error='Storage operation failed.'})}
